  "categories": [
    {
      "id": "initial-allowlist",
      "label": "Initial Allowlist Baseline",
      "description": "Initial creation of the AllowedSPI.toml and AllowedSPI-legacy.toml baseline files."
    },
    {
      "id": "new-feature-or-enhancement",
      "label": "New Feature / Enhancement SPI",
      "description": "Adding SPI allowlist entries to enable a new web platform feature, OS integration, or engine capability."
    },
    {
      "id": "cleanup-remove-spi",
      "label": "Cleanup / Remove SPI Use",
      "description": "Removing SPI allowlist entries after adopting public API replacements, refactoring, or deleting unneeded private API calls."
    },
    {
      "id": "feature-removal",
      "label": "Feature Removal",
      "description": "Removing an entire deprecated feature and all of its associated private APIs."
    },
    {
      "id": "sdkdb-or-api-promotion",
      "label": "SDKDB Baseline / Public API Promotion",
      "description": "Removing or conditioning SPI allowlist entries after Apple promoted the APIs to public in a newer iOS SDK / SDKDB baseline."
    },
    {
      "id": "bugfix-or-security-spi",
      "label": "Bug Fix / Security / Hardening SPI",
      "description": "Adding or updating SPI allowlist entries to fix a bug, crash, rendering regression, or security/memory-safety issue."
    },
    {
      "id": "refactor-or-code-movement",
      "label": "Refactoring / Cross-Module Code Movement",
      "description": "Moving SPI allowlist entries between WebKit modules (e.g. WebCore to WebKit) or upstreaming code from WebKitAdditions."
    },
    {
      "id": "build-or-conditional-fix",
      "label": "Build / Conditional / Symbol Fix",
      "description": "Adding or adjusting `requires`, `requires-sdk`, `allow-unused`, or debug/release Swift symbol conditionals to fix build errors."
    },
    {
      "id": "tooling-or-format-migration",
      "label": "Audit Tooling & Schema Migration",
      "description": "Updating allowlists for `audit-spi` schema or matching changes (selector class disambiguation, `[[reason]]` tables, C-style symbol names, `swift-decls`)."
    },
    {
      "id": "revert",
      "label": "Revert",
      "description": "Reverting a previous commit that caused build breakage, test failures, or regressions."
    }
  ],
  "legacy_addition_categories": [
    {
      "id": "tooling-disambiguation-or-swift-mangling",
      "label": "Tooling Selector Disambiguation & Swift Decls Migration",
      "description": "Additions to AllowedSPI-legacy.toml caused by audit-spi tooling upgrades: (1) adding receiver `class` disambiguation to selectors (b9fa7bcf1170), which uncovered 90 pre-existing private selectors/classes previously masked by name collisions with public selectors, and (2) replacing 65 mangled Swift symbol names with 42 demangled `swift-decls` entries (8a4f2c1e1043)."
    },
    {
      "id": "new-feature-or-bugfix-bypassing-reviewed-allowlist",
      "label": "New Feature / Bug-Fix SPI Added Directly to Legacy Allowlist",
      "description": "Genuine new private API usage added directly to `AllowedSPI-legacy.toml` instead of `AllowedSPI.toml` (e.g. Siri AI long-press image context `UIIntelligenceSupport` declarations, Site Isolation high-value fraud domain queries, `<model>` Tab Overview caching flags, `AVSpeechSynthesizer` super-compact voices, `WebAVPlayerLayerView.webPlayerLayer`, and `nw_settings_get_unified_http_enabled_webkit`), bypassing the requirement to provide `request` / `cleanup` radar URLs."
    },
    {
      "id": "sdk-or-build-configuration-backfill",
      "label": "SDK Baseline / Non-Default Build Configuration Backfill",
      "description": "Adding or re-adding conditional entries (`USE_APPLE_INTERNAL_SDK`, `!NDEBUG`, `HAVE_SUPPORT_HDR_DISPLAY_APIS`, `HAVE_WEBCONTENTANALYSIS_FRAMEWORK`, `HAVE_UIINTELLIGENCESUPPORT_FRAMEWORK`, `!SDKDB_HAS_*`, `requires-sdk`) to `AllowedSPI-legacy.toml` when internal SDK baseline updates or non-default build configurations failed `audit-spi`."
    },
    {
      "id": "cross-module-refactor-or-softlink-consolidation",
      "label": "Cross-Module Refactoring & Soft-Link Consolidation",
      "description": "Moving existing code between WebKit modules (e.g. moving `NetworkStorageSession` cookie SPIs from `WebCore` to `WebKit` in 920227936f2c) or consolidating `AVKit` soft-linking headers in `WebCore` (39f4250d8cda), causing `AllowedSPI-legacy.toml` in the receiving module to grow."
    },
    {
      "id": "revert-or-regression-restoration",
      "label": "Reverts & Crash/Regression Restorations",
      "description": "Re-adding legacy SPIs after reverting a public-API migration or restoring a removed SPI to fix runtime crashes or scrolling regressions (`CGIOSurfaceContextGetBitmapInfo`, `_setAvoidsJumpOnInterruptedBounce:`, `setTracksImmediatelyWhileDecelerating:`, `CGShadingCreateConic`)."
    }
  ],
